using System.Numerics;
using System.Reflection;
using System.Text.Json;
using Il2Cpp;
using LastEpochLAN.Mod.OfflineTools;
using UVec=UnityEngine.Vector3;
using Time=UnityEngine.Time;
var checks=new List<string>();
void Check(bool ok,string text){if(!ok)throw new Exception("FAIL: "+text);checks.Add(text);Console.WriteLine("PASS: "+text);}
object Prefix(Type t,params object[] args)=>t.GetMethod("Prefix",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,args);
Check(PickupRules.Within(Vector3.Zero,new Vector3(3,0,0),true),"radius includes exact3world units");
Check(!PickupRules.Within(Vector3.Zero,new Vector3(3.001f,0,0),true),"radius excludes beyond3");
Check(!PickupRules.Within(Vector3.Zero,new Vector3(2.2f,0,2.2f),true),"circle excludes diagonal outside radius");
Check(PickupRules.Within(Vector3.Zero,new Vector3(0,30,2),true),"distance uses horizontal circle like Combat Assist");
Check(!PickupRules.Within(Vector3.Zero,Vector3.Zero,false),"stationary character cannot auto-pick even underfoot");
Check(!PickupRules.Within(Vector3.Zero,new Vector3(float.NaN,0,0),true),"nonfinite location rejected");
Check(PickupRules.HasMoved(Vector3.Zero,new Vector3(.01f,0,0),.016),"actual horizontal movement detected");
Check(!PickupRules.HasMoved(Vector3.Zero,new Vector3(0,1,0),.016),"vertical idle movement does not count");
Check(!PickupRules.HasMoved(Vector3.Zero,new Vector3(20,0,0),.016),"teleport does not trigger sweeping");
Check(!PickupRules.HasMoved(Vector3.Zero,Vector3.One,1),"stale frame does not count as movement");
Check(!PickupRules.HasMoved(Vector3.Zero,Vector3.One,0),"duplicate timestamps do not count as movement");
var actor=PlayerFinder.Player;var manager=GroundItemManager.instance;
void Frame(float step,double dt=.1){Time.frameCount++;Time.realtimeSinceStartupAsDouble+=dt;Time.unscaledTime=(float)Time.realtimeSinceStartupAsDouble;actor.Position=new UVec(actor.Position.x+step,0,0);OfflinePickup.Tick();}
T Ground<T>(float x,uint id)where T:PickupGroundObjectInteraction,new()=>new(){player=actor,id=id,transform=new UnityEngine.Transform{position=new UVec(x,0,0)}};
GroundItemManager.GroundItem ItemAt(int type,float x,uint id,bool tutorial=false)=>new(){id=id,itemData=new ItemData{itemType=type,Tutorial=tutorial},location=new UVec(x,0,0)};
manager.activeGoldPiles.Add(Ground<GoldPickupInteraction>(2,1));manager.activeGoldPiles.Add(Ground<GoldPickupInteraction>(10,2));
manager.activePotions.Add(Ground<PotionPickupInteraction>(2,1));manager.activeAncientBones.Add(Ground<PickupAncientBonesInteraction>(2,1));
manager.offlineItems.items.AddRange(new[]{ItemAt(100,2,1),ItemAt(101,2,2),ItemAt(100,10,3),ItemAt(1,2,4),ItemAt(100,2,5,true)});
Frame(0);Frame(0);
Check(manager.Gold==0 && manager.Bones==0 && manager.Keys==0 && manager.Materials==0 && actor.Potion.currentCharges==0,"all automatic types stay on ground while standing");
var gate=typeof(OfflineNativeAutoPickupGatePatch);
Check(!(bool)Prefix(gate,manager.activeGoldPiles[0]),"native gold trigger cannot bypass stationary rule");
Check((bool)Prefix(gate,Ground<OtherPickupInteraction>(2,99)),"unrelated pickup types retain native triggers");
Frame(.1f);
Check(manager.Gold==10 && manager.Bones==3 && actor.Potion.currentCharges==1,"moving within3 picks gold,potion,bones via native operations");
Check(manager.Keys==1 && manager.Materials==1,"moving within3 picks enabled keys and crafting materials");
Check(manager.activeGoldPiles.Count==1 && manager.activeGoldPiles[0].id==2 && manager.offlineItems.items.Any(i=>i.id==3),"far gold and keys remain on ground");
Check(manager.Equipment==0 && manager.offlineItems.items.Any(i=>i.id==4),"equipment never auto-picked");
Check(manager.offlineItems.items.Any(i=>i.id==5),"tutorial key never auto-picked");
Check(manager.VacuumCalls==0 && AutomaticPickupScope.Depth==0,"automatic stackable pickup cannot vacuum outside the3circle");
Check(!(bool)Prefix(gate,manager.activeGoldPiles[0]),"native trigger also refuses moving pickup outside3");
manager.offlineItems.items.Add(ItemAt(100,2,6));Frame(0);
Check(manager.Keys==1,"stopping immediately stops automatic key pickup");
OfflineToolkit.Settings.Keys=false;Frame(.1f);Check(manager.Keys==1,"key toggle disables automatic pickup while moving");OfflineToolkit.Settings.Keys=true;
actor.Potion.currentCharges=actor.Potion.maxCharges;manager.activePotions.Add(Ground<PotionPickupInteraction>(2,2));Frame(.1f);
Check(manager.activePotions.Count==1 && actor.Potion.currentCharges==actor.Potion.maxCharges,"full potion charges leave ground potion untouched");
var other=Ground<GoldPickupInteraction>(2,3);other.player=new Actor();manager.activeGoldPiles.Add(other);Frame(.1f);
Check(manager.activeGoldPiles.Contains(other),"another player's private ground gold is untouched");
manager.offlineItems.items.Add(ItemAt(100,2,7));manager.ThrowOnItem=true;
try{Frame(.1f);}catch(InvalidOperationException){}
Check(AutomaticPickupScope.Depth==0,"native pickup exception restores vacuum suppression scope");manager.ThrowOnItem=false;
using(var scope=new AutomaticPickupScope()){using(var nested=new AutomaticPickupScope())Check(AutomaticPickupScope.Depth==2,"nested auto scopes retain suppression");Check(AutomaticPickupScope.Depth==1,"nested scope restores parent");}
Check((bool)Prefix(typeof(OfflineAutoPickupVacuumGatePatch)),"native vacuum remains available outside auto scope");
OfflineToolkit.Ready=false;Frame(.1f);Check(AutomaticPickupScope.Depth==0 && !OfflinePickup.CanAutoPick(actor,new UVec(2,0,0)),"inactive toolkit does not collect");OfflineToolkit.Ready=true;
OfflinePickup.Clear();Frame(.1f);Check(!OfflinePickup.Moving(actor),"scene reset discards movement from previous scene");
var data=manager.offlineItems.items.Single(i=>i.id==4).itemData;
Check(!(bool)Prefix(typeof(OfflineRangePickupPatch),new GroundItemLabel{Data=data}) && manager.Equipment==1,"explicit range click keeps equipment pickup while standing");
Console.WriteLine($"All {checks.Count} actual-source pickup checks passed; native gameplay not exercised.");
File.WriteAllText(args.Length>0?args[0]:"pickup-fixture.json",JsonSerializer.Serialize(new{passed=checks.Count,checks,nativeGameplayValidated=false},new JsonSerializerOptions{WriteIndented=true}));
